import sys
from collections import deque

def bfs(n, initial_positions, diag):
    queue = deque([(initial_positions, 0, [])])
    visited = set()
    visited.add(tuple(sorted(initial_positions)))

    while queue:
        current_positions, moves, path = queue.popleft()

        if set(current_positions) == {1, 2, 3}:
            return moves, path

        for i in range(3):
            for j in range(n):
                if j + 1 not in current_positions and diag[current_positions[i] - 1][j] != '*':
                    new_positions = list(current_positions)
                    new_positions[i] = j + 1
                    new_positions.sort()
                    new_tuple = tuple(new_positions)

                    if new_tuple not in visited:
                        visited.add(new_tuple)
                        queue.append((new_positions, moves + 1, path + [(current_positions[i], j + 1)]))

    return -1, []

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    initial_positions = list(map(int, data[1:4]))
    diag = [data[4 + i * n:4 + (i + 1) * n] for i in range(n)]

    moves, path = bfs(n, initial_positions, diag)

    if moves == -1:
        print(-1)
    else:
        print(moves)
        for move in path:
            print(move[0], move[1])

if __name__ == "__main__":
    main()
